package com.mangalens

import org.junit.Assert.*
import org.junit.Test

/** Actual source/frame samples from the checkpoint4 blank-before-decode capture. */
class ReaderSourceFrameOracleTest {
    @Test fun capturedBlankFrameCannotPassDecodedSourceReadiness() {
        assertTrue(ReaderSourceFrameOracle.matchingSamples(source, blank) * 100 < source.size * 80)
    }
    @Test fun capturedSourceSamplesPassAndUniformWhiteFrameFails() {
        assertEquals(source.size, ReaderSourceFrameOracle.matchingSamples(source, source.copyOf()))
        assertTrue(ReaderSourceFrameOracle.matchingSamples(source, IntArray(source.size) { -1 }) * 100 < source.size * 80)
    }
